svg:
  .contenedor {
display: flex;
gap: 20px;
font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
padding: 10px 4px;
box-sizing: border-box;
}
.card-izq {
width: 55%;
padding: 22px;
background: linear-gradient(135deg, #0f172a, #111827);
border: 1px solid #1e293b;
border-radius: 18px;
box-shadow: 0 8px 16px rgba(0,0,0,0.25);
color: #e2e8f0;
box-sizing: border-box;
}
.card-izq h3 {
margin: 0 0 12px 0;
color: #f8fafc;
font-size: 19px;
}
.card-izq p {
margin: 0;
font-size: 14px;
line-height: 1.6;
}
.card-izq ul {
margin: 12px 0 0 0;
padding-left: 18px;
font-size: 13.5px;
line-height: 1.75;
}
kbd {
background-color: #1e293b;
border: 1px solid #475569;
border-radius: 4px;
padding: 1px 5px;
font-size: 12px;
font-family: monospace;
}
.card-der {
width: 45%;
padding: 20px 22px;
background: #0b1120;
border: 1px solid #38bdf8;
border-radius: 18px;
box-shadow: 0 8px 16px rgba(56, 189, 248, 0.12);
font-family: ui-monospace, SFMono-Regular, Consolas, monospace;
font-size: 13px;
line-height: 1.65;
color: #e2e8f0;
box-sizing: border-box;
display: flex;
flex-direction: column;
justify-content: center;
}
.key { color: #7ee787; }
.str { color: #7dd3fc; }
